#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# ──────────────────────────────────────────────────────────────────────────
# STAGES — OAuth app do LTT quan ly (tang `cloud`, Q4 = C).
#
# 🔴 VI SAO CAN MOT WIZARD, KHONG PHAI MOT DOAN MA.
#    Dang ky OAuth app tren dashboard cua Google/Slack/GitHub/Notion la viec
#    CHI CHU DU AN lam duoc: no doi tai khoan that, doi dong y dieu khoan, va
#    no sinh ra mot `client_secret`. ⛔ Khong mot agent nao duoc tu nhap bi mat
#    cua chu du an vao mot dashboard, va ⛔ khong duoc bia mot luong gia vo
#    hoat dong. Nen: script dan tung buoc, nguoi lai trinh duyet, script chi
#    ghi gia tri vao dung cho.
#
# ⛔ `secrets\app.env` KHONG BAO GIO vao git (CLAUDE.md: "khong commit hay copy
#    di": `data/config.json` · `data/*.enc` · `secrets/` · `cloudflare/*`).
#
# ⚠️ MOT OAuth client cua Google phuc vu CA BON dich vu Google (Gmail, Drive,
#    Sheets, YouTube), nhung may chu khoa tang `cloud` THEO NHA CUNG CAP, nen
#    cung mot cap gia tri di vao BON cap bien. Do la co y: mot ngay nao Drive
#    dung app khac Gmail thi khong phai sua ma.
#
# Doc them: `apps/agent/routes/ket_noi_v3.py` (docstring mo-dun, phan "Hai TANG
# xac thuc"), va `python tools/i18n.py` khong lien quan gi o day.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

# Bi mat cua nen tang song o `secrets\app.env`, khong o `.env` cua kho.
ENV_FILE="${ENV_FILE:-/c/LTTPlatform/secrets/app.env}"

banner "LTT Agent — OAuth app cho tang 'cloud'"

# ── Stage 1: xac nhan cho ghi + URI chuyen huong ───────────────────────────
stage "Chuan bi: tep bi mat va URI chuyen huong"
say "Wizard nay ghi client id/secret vao tep bi mat cua nen tang."
note "tep: $ENV_FILE"
warn "Tep nay ⛔ KHONG BAO GIO vao git. Neu duong dan tren sai, Ctrl-C roi chay lai voi ENV_FILE=<duong dan>."
if [[ ! -d "$(dirname "$ENV_FILE")" ]]; then
  warn "thu muc $(dirname "$ENV_FILE") khong ton tai — may nay co phai may chu?"
  confirm "Van tiep tuc?" || exit 1
fi
say ""
say "Moi dashboard se hoi mot 'redirect URI' / 'callback URL'. Ca bon nha cung"
say "cap phai dung CUNG mot gia tri."
warn "Cua callback CHUA duoc cai dat (lan UI-5 dung o phan CAU TRUC). Dang ky"
warn "dia chi nay bay gio la dung thu tu: co app truoc, noi day sau."
ask LTT_OAUTH_REDIRECT_URI "URI chuyen huong [Enter = https://app.lttstudios.com/agent/api/v3/ket-noi/oauth/callback]:"
[[ -z "$LTT_OAUTH_REDIRECT_URI" ]] && \
  LTT_OAUTH_REDIRECT_URI="https://app.lttstudios.com/agent/api/v3/ket-noi/oauth/callback"
write_env LTT_OAUTH_REDIRECT_URI "$LTT_OAUTH_REDIRECT_URI"
pause "Ghi lai URI tren — ban se dan no vao bon dashboard."

# ── Stage 2: Google (Gmail · Drive · Sheets · YouTube) ────────────────────
stage "Google Cloud: MOT OAuth client cho bon dich vu"
if confirm "Cau hinh Google (Gmail, Drive, Sheets, YouTube) bay gio?"; then
  say "Mot OAuth client 'Web application' phuc vu ca bon."
  open_url "https://console.cloud.google.com/apis/credentials"
  step "Chon (hoac tao) project se dung cho LTT."
  step "Bam 'Create credentials' -> 'OAuth client ID'."
  step "Application type: 'Web application'."
  step "Authorized redirect URIs -> 'ADD URI' -> dan:"
  note "  $LTT_OAUTH_REDIRECT_URI"
  step "Bam 'Create'. Hop thoai hien 'Client ID' va 'Client secret'."
  warn "Neu Google doi 'OAuth consent screen' truoc: lam no xong roi quay lai."
  warn "Cac scope Gmail/Drive doc thu tin la scope HAN CHE — Google co the doi"
  warn "kiem duyet truoc khi mo cho nguoi dung ngoai. Do la viec cua ban, khong"
  warn "phai cua script nay."
  ask       GOOGLE_CLIENT_ID     "Dan Client ID cua Google:"
  ask_secret GOOGLE_CLIENT_SECRET "Dan Client secret cua Google:"
  # ⭐ MOT cap gia tri -> BON cap bien: may chu khoa tang `cloud` theo NHA CUNG
  #    CAP (`_bien_moi_truong` trong `ket_noi_v3.py`), va ma nha cung cap sinh
  #    tu catalog piece (`gmail`, `google_drive`, `google_sheets`) cong node
  #    `connector.youtube.*`.
  for p in GMAIL GOOGLE_DRIVE GOOGLE_SHEETS YOUTUBE; do
    write_env "LTT_OAUTH_${p}_CLIENT_ID" "$GOOGLE_CLIENT_ID"
    write_env "LTT_OAUTH_${p}_CLIENT_SECRET" "$GOOGLE_CLIENT_SECRET"
  done
else
  SKIPPED+=("Google (Gmail/Drive/Sheets/YouTube): khach se phai tu mang app")
fi

# ── Stage 3: Slack ────────────────────────────────────────────────────────
stage "Slack: OAuth app"
if confirm "Cau hinh Slack bay gio?"; then
  open_url "https://api.slack.com/apps"
  step "Bam 'Create New App' -> 'From scratch', dat ten va chon workspace."
  step "Trong app: 'OAuth & Permissions' -> 'Redirect URLs' -> 'Add New Redirect URL' -> dan:"
  note "  $LTT_OAUTH_REDIRECT_URI"
  step "Bam 'Save URLs'."
  step "Sang 'Basic Information' -> 'App Credentials' — do co Client ID; bam"
  step "'Show' o dong Client Secret de doc no."
  ask       SLACK_CLIENT_ID     "Dan Client ID cua Slack:"
  ask_secret SLACK_CLIENT_SECRET "Dan Client Secret cua Slack:"
  write_env LTT_OAUTH_SLACK_CLIENT_ID "$SLACK_CLIENT_ID"
  write_env LTT_OAUTH_SLACK_CLIENT_SECRET "$SLACK_CLIENT_SECRET"
else
  SKIPPED+=("Slack: khach se phai tu mang app")
fi

# ── Stage 4: GitHub ───────────────────────────────────────────────────────
stage "GitHub: OAuth App"
if confirm "Cau hinh GitHub bay gio?"; then
  say "Chon 'OAuth App', ⛔ khong phai 'GitHub App' — hai thu khac nhau, va"
  say "node GitHub cua nen tang dung luong OAuth App."
  open_url "https://github.com/settings/developers"
  step "Tab 'OAuth Apps' -> 'New OAuth App'."
  step "Application name: tu dat. Homepage URL: https://app.lttstudios.com"
  step "Authorization callback URL — dan:"
  note "  $LTT_OAUTH_REDIRECT_URI"
  step "Bam 'Register application'. Trang sau hien Client ID."
  step "Bam 'Generate a new client secret' va copy NGAY — GitHub chi hien mot lan."
  ask       GITHUB_CLIENT_ID     "Dan Client ID cua GitHub:"
  ask_secret GITHUB_CLIENT_SECRET "Dan Client secret cua GitHub:"
  write_env LTT_OAUTH_GITHUB_CLIENT_ID "$GITHUB_CLIENT_ID"
  write_env LTT_OAUTH_GITHUB_CLIENT_SECRET "$GITHUB_CLIENT_SECRET"
else
  SKIPPED+=("GitHub: khach se phai tu mang app (node GitHub cung nhan api_key)")
fi

# ── Stage 5: Notion ───────────────────────────────────────────────────────
stage "Notion: public integration"
if confirm "Cau hinh Notion bay gio?"; then
  say "Notion chi cap client id/secret cho integration 'Public'. Mot integration"
  say "'Internal' KHONG co OAuth — no chi co mot token cho chinh workspace ban."
  open_url "https://www.notion.so/my-integrations"
  step "'New integration' -> dat ten -> tao."
  step "Trong integration: tab 'Distribution' -> bat 'public integration'."
  step "Dien cac truong Notion doi (ten to chuc, website, privacy policy...)."
  step "Redirect URIs -> dan:"
  note "  $LTT_OAUTH_REDIRECT_URI"
  step "Luu, roi sang tab 'Configuration' de doc OAuth client ID va secret."
  ask       NOTION_CLIENT_ID     "Dan OAuth client ID cua Notion:"
  ask_secret NOTION_CLIENT_SECRET "Dan OAuth client secret cua Notion:"
  write_env LTT_OAUTH_NOTION_CLIENT_ID "$NOTION_CLIENT_ID"
  write_env LTT_OAUTH_NOTION_CLIENT_SECRET "$NOTION_CLIENT_SECRET"
else
  SKIPPED+=("Notion: khach se phai tu mang app")
fi

# ── Stage 6: nap lai ENV va DOI CHUNG ────────────────────────────────────
stage "Nap lai ENV, roi DOI CHUNG bang chinh cua may chu"
warn "Restart-Service la KHONG DU: nssm nuong ENV luc CAI. Du an nay da dinh ba lan."
say "Chay (PowerShell, quyen Administrator):"
note "  powershell -File setup\\nap_lai_env.ps1"
pause "Da chay xong?"
say ""
say "DOI CHUNG — ⛔ dung tin script nay, hoi may chu:"
note "  https://app.lttstudios.com/agent/api/v3/ket-noi/nha-cung-cap"
step "Voi moi nha cung cap ban vua cau hinh, JSON phai co:"
note '  "san_sang": true   va   "ly_do": ""'
step "Nha cung cap nao van bao \"chua_cau_hinh\" thi hai bien cua no chua toi"
step "tien trinh web — kiem lai ten bien trong $ENV_FILE."
warn "Neu 'san_sang' van false: giao dien se noi \"LTT chua cau hinh cho nha"
warn "cung cap nay\" va khach van tao duoc ket noi bang app CUA HO. Khong hong,"
warn "chi la tang 'cloud' chua bat."

finish
